import{_ as t,o,c as r,a2 as a}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"Overview","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md"}'),d={name:"guide/index.md"};function n(i,e,s,c,h,l){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Unofficial · reverse-engineered</p><p>A community reference for the ground-up <strong>.NET 10</strong> C# runtime that ships in the <code>net10test</code> resource set. Every page here was written by reading the decompiled <code>CitizenFX.Base</code>, <code>CitizenFX.FiveM.Shared</code>, <code>CitizenFX.FiveM.Client</code> and <code>CitizenFX.FiveM.Server</code> assemblies — because the framework is new and there are, as yet, no official docs.</p></div><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>TFM</strong></td><td><code>net10.0</code></td></tr><tr><td><strong>Assembly version</strong></td><td>1.0.0.0</td></tr><tr><td><strong>Serializer</strong></td><td>MessagePack</td></tr><tr><td><strong>Root namespace</strong></td><td><code>CitizenFX.FiveM.*</code></td></tr><tr><td><strong>Facades</strong></td><td><code>API</code> · <code>SharedAPI</code></td></tr></tbody></table><h2 id="what-this-is" tabindex="-1">What this is <a class="header-anchor" href="#what-this-is" aria-label="Permalink to &quot;What this is&quot;">​</a></h2><p><strong>A brand-new runtime, not a patch on the old one.</strong></p><p>If you have written FiveM C# before, you know <code>CitizenFX.Core</code>: one big assembly on an embedded Mono, where you inherit <code>BaseScript</code> and use <code>[EventHandler]</code>, <code>Exports</code>, and <code>Tick += …</code>. <strong>This is a different framework.</strong> It targets real <strong>.NET 10</strong>, splits the old monolith into four small assemblies, and replaces inheritance with a tiny <code>IScript</code> marker interface plus attributes. The whole argument pipeline is the mainstream <a href="./serialization.html">MessagePack</a> library, end to end.</p><table tabindex="0"><thead><tr><th>Concept</th><th>Legacy CitizenFX.Core</th><th>This .NET 10 runtime</th></tr></thead><tbody><tr><td>Script base</td><td><code>BaseScript</code> (inherit)</td><td><code>IScript</code> (marker interface)</td></tr><tr><td>Entry API</td><td><code>Function.Call</code>, <code>Exports</code></td><td><code>API</code> (per side) &amp; <code>SharedAPI</code></td></tr><tr><td>Event handler</td><td><code>[EventHandler(&quot;x&quot;)]</code></td><td><code>[OnEvent]</code> / <code>[OnNetEvent]</code></td></tr><tr><td>Command</td><td><code>RegisterCommand(...)</code></td><td><code>[OnCommand(&quot;x&quot;)]</code></td></tr><tr><td>Export</td><td><code>Exports.Add(...)</code></td><td><code>[ExportMethod(&quot;x&quot;)]</code></td></tr><tr><td>Natives</td><td><code>Function.Call&lt;T&gt;(Hash.X, …)</code></td><td>typed <code>Native.X(…)</code></td></tr><tr><td>Tick loop</td><td><code>Tick += handler</code></td><td><code>SetInterval</code> / async + <code>Delay</code></td></tr><tr><td>Framework</td><td>Mono</td><td><code>net10.0</code></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Scope &amp; disclaimer</p><p>This documentation is community work, unaffiliated with Cfx.re, reconstructed from one decompiled build (<code>net10test</code>, assemblies v1.0.0.0). It describes what the code <em>does</em>, which is the most reliable source available — but names and behaviour may shift in newer runtime versions. Verify against your own server&#39;s assemblies.</p></div><h2 id="where-to-start" tabindex="-1">Where to start <a class="header-anchor" href="#where-to-start" aria-label="Permalink to &quot;Where to start&quot;">​</a></h2><ul><li><strong><a href="./tour.html">A tour of these docs</a></strong> — new here? Two minutes on how the site is organized.</li><li><strong><a href="./getting-started.html">Creating a resource</a></strong> — from an empty folder to a working client + server round-trip: layout, manifest, <code>net10.0</code> csproj, first script.</li><li><strong><a href="./architecture.html">Architecture &amp; boot</a></strong> — the three layers, and the exact sequence the host uses to construct the runtime and discover your scripts.</li><li><strong><a href="./threading.html">Threading &amp; TickManager</a></strong> — what the TickManager actually is, whether you can spin up threads, and how to get back to the main thread.</li><li><strong><a href="./api-reference.html">API reference</a></strong> — every member of <code>API</code> (client &amp; server) and <code>SharedAPI</code>, in one place.</li><li><strong><a href="./migrating-from-lua.html">Migrating from Lua</a></strong> — side-by-side translations of the patterns you already know.</li></ul><h2 id="the-mental-model-in-one-minute" tabindex="-1">The mental model in one minute <a class="header-anchor" href="#the-mental-model-in-one-minute" aria-label="Permalink to &quot;The mental model in one minute&quot;">​</a></h2><ul><li>You ship one or more assemblies containing classes that implement <strong><code>IScript</code></strong>. The runtime scans every loaded assembly, instantiates each one, and wires up its attributed methods.</li><li>You talk to the world through the static <strong><code>API</code></strong> facade (client or server) and the side-agnostic <strong><code>SharedAPI</code></strong>. There&#39;s no object to hold onto.</li><li>Everything runs on <strong>one main thread</strong>, pumped by the <a href="./threading.html"><code>TickManager</code></a>. <code>async/await</code> works and resumes there.</li><li>Data crossing any boundary — events, exports, commands, function references — is <a href="./serialization.html">MessagePack</a>-serialized. Entities travel as their handles / network ids.</li><li>Game and server functions are <a href="./natives.html">strongly-typed <code>Native.X(…)</code></a> methods built on a function-pointer table handed to <a href="./native-bridge.html">CitizenFX.Base</a> by the host.</li></ul>',12)])])}const g=t(d,[["render",n]]);export{u as __pageData,g as default};
